const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const n = input[0];

let substituir = 0;
let consertar = 0;

for (let i = 1; i <= n; i++) {
  if (input[i] < 50) substituir++;
  else if (input[i] < 85) consertar++;
}

console.log(`${substituir} ${consertar}`);
